CREATE TABLE `creator_commissions` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`handle` text NOT NULL,
	-- Nullable on purpose. The subscriber can delete their account, and the creator is still owed
	-- for invoices already paid, so deletion clears this column instead of removing the row. See
	-- ANONYMISED_TABLES in app/account-deletion.ts.
	`user_id` text,
	`invoice_id` text NOT NULL,
	`subscription_id` text,
	`gross_amount` integer NOT NULL,
	`currency` text NOT NULL,
