CREATE TRIGGER trg_reports_inserted AFTER INSERT ON reports
WHEN NEW.category IN ('deal_ended','incorrect_price','incorrect_schedule','restaurant_closed','wrong_location','misleading_terms')
BEGIN
  UPDATE data_changes SET n = n + 1 WHERE name = 'reports';
END;
CREATE TRIGGER trg_reports_status_changed AFTER UPDATE OF status ON reports
WHEN OLD.status IS NOT NEW.status
  AND NEW.category IN ('deal_ended','incorrect_price','incorrect_schedule','restaurant_closed','wrong_location','misleading_terms')
BEGIN
  UPDATE data_changes SET n = n + 1 WHERE name = 'reports';
END;
CREATE TRIGGER trg_reports_deleted AFTER DELETE ON reports
WHEN OLD.category IN ('deal_ended','incorrect_price','incorrect_schedule','restaurant_closed','wrong_location','misleading_terms')
BEGIN
  UPDATE data_changes SET n = n + 1 WHERE name = 'reports';
END;
CREATE TRIGGER `trg_audit_log_no_update` BEFORE UPDATE ON `audit_log`
BEGIN
  SELECT RAISE(ABORT, 'audit_log is append-only');
END;
CREATE TRIGGER `trg_audit_log_no_delete` BEFORE DELETE ON `audit_log`
BEGIN
  SELECT RAISE(ABORT, 'audit_log is append-only');
END;

